import{levels,indexedSalary,ageGroup,allowance,sumPoints,gap}from'./core.mjs';
const $=id=>document.getElementById(id);let data,rows=[];
const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(n);
const option=(v,t)=>{const el=document.createElement('option');el.value=v;el.textContent=t;return el;};
function readRows(){return [...document.querySelectorAll('.exercise')].map(el=>({exercise:el.querySelector('select').value,result:el.querySelector('[data-result]').value,points:el.querySelector('[data-points]').value}));}
function renderRows(){rows=readRows();const n=Number($('count').value);$('exercises').replaceChildren();for(let i=0;i<n;i++){const row=rows[i]||{exercise:['3','17','20','1','18'][i],result:'',points:''};const box=document.createElement('div');box.className='exercise';box.innerHTML=`<div class="exercise-title"><span>УПРАЖНЕНИЕ ${String(i+1).padStart(2,'0')}</span><span class="patch">Результат</span></div><label>Упражнение<select aria-label="Упражнение ${i+1}"></select></label><div class="fields"><label>Результат<input data-result type="text" maxlength="32" placeholder="Например: 12 раз или 14:30"></label><label>Баллы из ведомости<input data-points type="number" min="0" max="100" step="1" inputmode="numeric" placeholder="0–100"></label></div>`;const select=box.querySelector('select');select.append(option('','Выбери упражнение'));for(const x of data.exercises){if($('sex').value==='men'&&x.id.includes('_w'))continue;select.append(option(x.id,x.name.replace('Упр. № ','№ ')));}select.value=row.exercise;box.querySelector('[data-result]').value=row.result;box.querySelector('[data-points]').value=row.points;const patch=box.querySelector('.patch');const setPatch=()=>{const x=data.exercises.find(x=>x.id===select.value);patch.textContent={strength:'Сила',speed:'Быстрота',stamina:'Выносливость',agility:'Ловкость',specExercise:'Спецподготовка'}[x?.kind]||'Результат';};select.addEventListener('change',()=>{box.querySelector('[data-result]').value='';box.querySelector('[data-points]').value='';setPatch();update();});setPatch();$('exercises').append(box);}}
function clearResult(message){$('levelDisplay').textContent=message;$('amount').textContent='— ₽';$('percent').textContent='Проверь введённые данные';$('gain').textContent='Расчёт пока недоступен';$('gap').textContent='—';}
function update(){const values=readRows();const total=sumPoints(values.map(x=>x.points));$('total').textContent=$('scoreDisplay').textContent=total??'—';const female=$('sex').value==='women';$('categoryField').hidden=female;$('sportConditions').hidden=$('sport').value==='0';let group;try{group=ageGroup(Number($('age').value));}catch(e){$('profile').textContent=e.message;clearResult('Проверь возраст');return;}
 const salary=indexedSalary(data.salary2019[Number($('grade').value)-1]);const rank=Number($('rank').value);$('salary').textContent=money(salary);$('rankSalary').textContent=money(indexedSalary(data.ranks[rank][1]));$('profile').textContent=`${female?'Женщина':'Мужчина'} · ${$('age').value} лет · ${group}-я возрастная группа${female?'':` · категория ${$('category').value}`}`;$('gradeDisplay').textContent=`Тарифный разряд ${$('grade').value} · ${data.ranks[rank][0]}`;
 const invalid=values.some(x=>x.points!==''&&(!Number.isInteger(Number(x.points))||Number(x.points)<0||Number(x.points)>100));if(invalid){clearResult('Баллы должны быть от 0 до 100');return;}
 const level=$('level').value;const row=levels.find(x=>x[0]===level);let current=null;if(row){current=allowance(salary,level);$('levelDisplay').textContent=row[1];$('amount').textContent=money(current.amount);$('percent').textContent=`${current.percent}% от оклада по должности · по выбранному уровню`;}else{$('levelDisplay').textContent='Выбери свой уровень';$('amount').textContent='— ₽';$('percent').textContent='Уровень берётся из официальной ведомости';}
 const target=levels.find(x=>x[0]===$('targetLevel').value);const raw=$('targetPoints').value;const points=Number(raw);if(raw===''||!Number.isInteger(points)||points<0||points>500){$('gap').textContent='Укажи нужный порог баллов';}else if(total===null){$('gap').textContent='Внеси баллы всех упражнений';}else{const g=gap(total,points);$('gap').textContent=g===0?'Порог суммы уже набран':`Осталось набрать ${g} балл${g%10===1&&g%100!==11?'':g%10>=2&&g%10<=4&&(g%100<12||g%100>14)?'а':'ов'}`;}
 if(!current){$('gain').textContent='Выбери текущий уровень для сравнения';}else{const diff=Math.max(0,allowance(salary,target[0]).amount-current.amount);$('gain').textContent=diff>0?`${target[1]}: возможные +${money(Math.round(diff*100)/100)} в месяц`:'Выбранная цель не увеличивает надбавку';}
 $('resultExercises').replaceChildren();for(const x of values){if(!x.exercise)continue;const name=data.exercises.find(e=>e.id===x.exercise)?.name||x.exercise;const el=document.createElement('div');const text=document.createElement('span');text.textContent=name.replace(/^Упр\. № /,'№ ') + (x.result?` · ${x.result}`:'');const b=document.createElement('b');b.textContent=x.points===''?'—':`${x.points} б.`;el.append(text,b);$('resultExercises').append(el);}}
try{const response=await fetch('./data.json');if(!response.ok)throw Error();data=await response.json();data.salary2019.forEach((_,i)=>$('grade').append(option(i+1,`${i+1} разряд`)));data.ranks.forEach((r,i)=>$('rank').append(option(i,r[0])));$('grade').value='10';$('rank').value='9';renderRows();$('loading').hidden=true;$('app').hidden=false;update();$('form').addEventListener('input',update);$('form').addEventListener('change',update);$('count').addEventListener('change',()=>{renderRows();update();});$('sex').addEventListener('change',()=>{rows=[];$('exercises').replaceChildren();renderRows();update();});$('form').addEventListener('submit',e=>{e.preventDefault();update();$('result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('result').focus({preventScroll:true});});$('form').addEventListener('reset',()=>setTimeout(()=>{rows=[];$('exercises').replaceChildren();$('grade').value='10';$('rank').value='9';renderRows();update();},0));}catch{$('loading').textContent='Не удалось загрузить данные. Обнови страницу или попробуй позже.';}
